GRPO RLVR Recovery Training for pruned models.

Uses trl.GRPOTrainer with GSM8K answer-matching reward to recover
reasoning ability of structurally pruned models.

v4: reward desert detection, disk-friendly checkpointing, max_completion_length=4096
v5: low-temperature sampling + repetition_penalty to combat degenerate repetition
    (--temperature, --repetition_penalty, --top_p, --top_k)
    --sampling_quality_check: pre-training sanity check on generation quality
"""

import argparse
import logging
import os
import random
import re
from collections import Counter

import numpy as np
import torch
from datasets import load_dataset
from transformers import AutoTokenizer, TrainerCallback
from model_utils import load_pruned_model
from trl import GRPOConfig, GRPOTrainer

try:
    import wandb
except ImportError:
    wandb = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


class RewardDesertCallback(TrainerCallback):
    """Stop training if reward stays at zero for too many consecutive log events.

    v2 lesson: pruned model too weak -> reward=0 every sample -> loss=0,
    grad_norm=0, zero learning signal for hundreds of steps.
    """

    def __init__(self, patience: int = 50):
        self.patience = patience
        self.zero_reward_count = 0
        self.last_logged_step = -1

    def on_log(self, args, state, control, logs=None, **kwargs):
        if logs is None:
            return
        # trl GRPOTrainer logs reward under various keys depending on version
        reward_mean = logs.get("reward", logs.get("rewards/mean", None))
        if reward_mean is None:
            return
        if state.global_step == self.last_logged_step:
            return
        self.last_logged_step = state.global_step

        if reward_mean == 0.0:
            self.zero_reward_count += 1
            if self.zero_reward_count >= self.patience:
                logger.warning(
                    f"REWARD DESERT: reward=0 for {self.zero_reward_count} consecutive "
                    f"log events (~{self.zero_reward_count * args.logging_steps} steps). "
                    f"Pruned model may be too weak for GRPO. Stopping."
                )
                control.should_training_stop = True
        else:
            self.zero_reward_count = 0


def extract_answer(text: str) -> str | None:
    """Extract numeric answer from model output.
    Tries \\boxed{} first, then last number in text.
    """
    # Try \boxed{...}
    boxed = re.findall(r"\\boxed\{([^}]+)\}", text)
    if boxed:
        return boxed[-1].strip().replace(",", "")

    # Try #### format (GSM8K style)
    hash_match = re.findall(r"####\s*(.+)", text)
    if hash_match:
        return hash_match[-1].strip().replace(",", "")

    # Fall back to last number
    numbers = re.findall(r"-?\d+(?:,\d{3})*(?:\.\d+)?", text)
    if numbers:
        return numbers[-1].replace(",", "")
    return None


def normalize_answer(ans: str) -> str:
    """Normalize a numeric answer string for comparison."""
    ans = ans.strip().replace(",", "").replace(" ", "")
    try:
        val = float(ans)
        if val == int(val):
            return str(int(val))
        return str(val)
    except (ValueError, OverflowError):
        return ans


def extract_gold_answer(answer_text: str) -> str:
    """Extract gold answer from GSM8K answer field (after ####)."""
    match = re.search(r"####\s*(.+)", answer_text)
    if match:
        return normalize_answer(match.group(1))
    return answer_text.strip()


def build_reward_fn(tokenizer):
    """Build a reward function for GRPO that checks answer correctness."""

    def reward_fn(completions, **kwargs):
        """Reward function: 1.0 for correct answer, 0.0 for incorrect."""
        prompts = kwargs.get("prompts", None)
        gold_answers = kwargs.get("answer", None)

        rewards = []
        for i, completion in enumerate(completions):
            if isinstance(completion, list):
                # completion is list of message dicts
                text = completion[-1]["content"] if completion else ""
            else:
                text = completion

            pred = extract_answer(text)

            if gold_answers is not None and i < len(gold_answers):
                gold = normalize_answer(str(gold_answers[i]))
            else:
                gold = None

            if pred is not None and gold is not None:
                pred_norm = normalize_answer(pred)
                reward = 1.0 if pred_norm == gold else 0.0
            else:
                reward = 0.0
            rewards.append(reward)

        return rewards

    return reward_fn


def prepare_dataset(tokenizer, max_samples: int = None, seed: int = 42):
    """Prepare GSM8K train dataset for GRPO training."""
    ds = load_dataset("openai/gsm8k", "main", split="train")
    if max_samples is not None:
        ds = ds.shuffle(seed=seed).select(range(min(max_samples, len(ds))))

    def format_prompt(example):
        prompt = (
            f"Solve the following math problem step by step. "
            f"Put your final answer in \\boxed{{}}.\n\n"
            f"Question: {example['question']}\n\nAnswer:"
        )
        example["prompt"] = prompt
        example["answer"] = extract_gold_answer(example["answer"])
        return example

    ds = ds.map(format_prompt)
    return ds
